    async let b = backend.parseRecipeWithContract(.init(mode: .prompt, text: second))
    let (ra, rb) = try await (a, b)
    XCTAssertEqual(ra.card.title, "Chicken curry")
    XCTAssertEqual(rb.card.title, "Vegan pancakes")
